def chmod(mode, ekspresi):
    m = int(mode, 8)
    for klausa in ekspresi.split(","):
        i = 0
        while klausa[i] in "ugoa":
            i += 1
        siapa = "ugo" if (i == 0 or "a" in klausa[:i]) else klausa[:i]
        op, izin = klausa[i], klausa[i + 1:]
        nilai = sum({"r": 4, "w": 2, "x": 1}[c] for c in izin)
        for s in siapa:
            g = {"u": 6, "g": 3, "o": 0}[s]
            if op == "+":
                m |= nilai << g
            elif op == "-":
                m &= ~(nilai << g)
            else:
                m = (m & ~(7 << g)) | (nilai << g)
    return format(m & 0o777, "03o")

