def top_ip(baris, n):
    hitung = {}
    for b in baris:
        if b.strip():
            ip = b.split()[0]
            hitung[ip] = hitung.get(ip, 0) + 1
    urut = sorted(hitung.items(), key=lambda kv: (-kv[1], kv[0]))
    return [f"{c} {ip}" for ip, c in urut[:n]]

