            host = nilai
            hasil[host] = {}
        elif host is not None:
            hasil[host][kunci] = nilai
    return hasil


def perintah_ssh(config, nama):
    c = config[nama]
    bagian = ["ssh"]
    if "port" in c:
        bagian += ["-p", c["port"]]
    if "identityfile" in c:
        bagian += ["-i", c["identityfile"]]
    tujuan = c.get("hostname", nama)
    if "user" in c:
        tujuan = c["user"] + "@" + tujuan
    return " ".join(bagian + [tujuan])

