import shlex


class Terminal:
    def __init__(self):
        self.cwd = "/home/user"
        self.dirs = {"/", "/home", "/home/user"}
        self.files = {}  # path -> isi teks, tiap baris diakhiri "\n"

    def path(self, p):
        if p == "~" or p.startswith("~/"):
            p = "/home/user" + p[1:]
        if not p.startswith("/"):
            p = self.cwd + "/" + p
        bagian = []
        for x in p.split("/"):
            if x in ("", "."):
                continue
            if x == "..":
                if bagian:
                    bagian.pop()
            else:
                bagian.append(x)
        return "/" + "/".join(bagian)

    def induk(self, p):
        return p.rsplit("/", 1)[0] or "/"

    def run(self, baris):
        tahap = baris.split("|")
        data = ""
        for i, t in enumerate(tahap):
            data = self.satu(shlex.split(t), data, i == len(tahap) - 1)
            if data.startswith(self.GALAT):
                return data[len(self.GALAT):]
        return data

    GALAT = "\x00"

    def galat(self, pesan):
        return self.GALAT + pesan

    def baca(self, nama):
        p = self.path(nama)
        if p in self.files:
            return self.files[p]
        return None

    def satu(self, kata, stdin, terakhir):
        if not kata:
            return ""
        tujuan, mode = None, None
        for op in (">>", ">"):
            if op in kata and terakhir:
                k = kata.index(op)
                tujuan, mode = kata[k + 1], op
                kata = kata[:k] + kata[k + 2:]
                break
        cmd, arg = kata[0], kata[1:]
        out = self.perintah(cmd, arg, stdin)
        if out.startswith(self.GALAT):
            return out
        if tujuan is not None:
            p = self.path(tujuan)
            if self.induk(p) not in self.dirs or p in self.dirs:
                return self.galat(f"bash: {tujuan}: No such file or directory")
            isi = out + "\n" if out else ""
            self.files[p] = (self.files.get(p, "") if mode == ">>" else "") + isi
            return ""
        return out

    def perintah(self, cmd, arg, stdin):
        if cmd == "pwd":
            return self.cwd
        if cmd == "echo":
            return " ".join(arg)
        if cmd == "cd":
            tujuan = arg[0] if arg else "~"
            p = self.path(tujuan)
            if p in self.dirs:
                self.cwd = p
                return ""
            if p in self.files:
                return self.galat(f"cd: {tujuan}: Not a directory")
            return self.galat(f"cd: {tujuan}: No such file or directory")
        if cmd == "mkdir":
            buat_induk = "-p" in arg
            for d in [a for a in arg if a != "-p"]:
                p = self.path(d)
                if p in self.dirs or p in self.files:
                    if buat_induk and p in self.dirs:
                        continue
                    return self.galat(f"mkdir: cannot create directory '{d}': File exists")
                if buat_induk:
                    sekarang = ""
                    for x in p.strip("/").split("/"):
                        sekarang += "/" + x
                        self.dirs.add(sekarang)
                elif self.induk(p) in self.dirs:
                    self.dirs.add(p)
                else:
                    return self.galat(f"mkdir: cannot create directory '{d}': No such file or directory")
            return ""
        if cmd == "touch":
            for f in arg:
                p = self.path(f)
                if self.induk(p) not in self.dirs:
                    return self.galat(f"touch: cannot touch '{f}': No such file or directory")
                self.files.setdefault(p, "")
            return ""
        if cmd == "cat":
            if not arg:
                return stdin
            bagian = []
            for f in arg:
                isi = self.baca(f)
                if isi is None:
                    return self.galat(f"cat: {f}: No such file or directory")
                bagian.append(isi.rstrip("\n"))
            return "\n".join(b for b in bagian if b)
        if cmd == "ls":
            nama = arg[0] if arg else "."
            p = self.path(nama)
            if p not in self.dirs:
                return self.galat(f"ls: cannot access '{nama}': No such file or directory")
            awal = p.rstrip("/") + "/"
            anak = {x[len(awal):].split("/")[0] for x in list(self.dirs) + list(self.files) if x != p and x.startswith(awal)}
            return "\n".join(sorted(anak))
        if cmd == "grep":
            pola = arg[0]
            if len(arg) > 1:
                isi = self.baca(arg[1])
                if isi is None:
                    return self.galat(f"grep: {arg[1]}: No such file or directory")
            else:
                isi = stdin
            return "\n".join(b for b in isi.splitlines() if pola in b)
        if cmd == "wc":
            if len(arg) > 1:
                isi = self.baca(arg[1])
                if isi is None:
                    return self.galat(f"wc: {arg[1]}: No such file or directory")
            else:
                isi = stdin
            return str(len(isi.splitlines()))
        if cmd == "rm":
            for f in arg:
                p = self.path(f)
                if p in self.files:
                    del self.files[p]
                elif p in self.dirs:
                    return self.galat(f"rm: cannot remove '{f}': Is a directory")
                else:
                    return self.galat(f"rm: cannot remove '{f}': No such file or directory")
            return ""
        return self.galat(f"bash: {cmd}: command not found")

